import { state, icon, escapeHtml } from './core.js?v=d6fd58c3ef81';
import { isSafeHtmlUrl } from '../utils/escape-html.js?v=d6fd58c3ef81';

const WEEKDAYS = ['Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado', 'Domingo'];
const WEEKDAY_KEYS = ['seg', 'ter', 'qua', 'qui', 'sex', 'sab', 'dom'];

function dateKey(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function parseDate(value) {
  const [year, month, day] = String(value || '').slice(0, 10).split('-').map(Number);
  return year && month && day ? new Date(year, month - 1, day) : null;
}

function addDays(date, days) { const next = new Date(date); next.setDate(next.getDate() + days); return next; }
function mondayOf(date) { const result = new Date(date); result.setHours(0, 0, 0, 0); result.setDate(result.getDate() - ((result.getDay() + 6) % 7)); return result; }
function fmtDate(value, options = { day: '2-digit', month: 'short' }) { const date = value instanceof Date ? value : parseDate(value); return date ? new Intl.DateTimeFormat('pt-BR', options).format(date) : ''; }
function subjectName(id) { return (window.M2Data.subjects || []).find(subject => String(subject.id) === String(id))?.name || 'Estudo dirigido'; }
function topicName(id) { return (window.M2Data.syllabus || []).flatMap(subject => subject.topics || []).find(topic => String(topic.id) === String(id))?.name || (window.M2Data.topics || []).find(topic => String(topic.id) === String(id))?.name || 'Conteúdo do edital'; }

function scheduleItems({ calendar = false } = {}) {
  const loaded = calendar && state.calendarRangeKey ? state.calendarItems : (window.M2Data.scheduleItems || []);
  return loaded.map(item => ({ ...item, planned_date: item.planned_date ? String(item.planned_date).slice(0, 10) : null, duration_minutes: Number(item.duration_minutes || 60), status: item.status || 'pendente', isReview: Boolean(item.scheduled_review_id), subjectLabel: subjectName(item.subject_id), topicLabel: topicName(item.topic_id) }));
}

function planDraft() {
  if (state.planDraft) return state.planDraft;
  const levels = {}; const selected = {};
  (window.M2Data.subjects || []).forEach(subject => { levels[subject.id] = 'intermediario'; selected[subject.id] = true; });
  const canUseSmartCycle = (window.M2Data.capabilities || []).includes('cronograma_inteligente');
  state.planDraft = { contestId: state.contestId || window.M2Data.contests?.[0]?.id || '', mode: canUseSmartCycle ? 'ciclo_inteligente' : 'agendado', hours: { seg: 2, ter: 2, qua: 2, qui: 2, sex: 2, sab: 2, dom: 0 }, minutes: 60, maxTopics: 0, repetitions: 1, goal: 80, levels, selected };
  return state.planDraft;
}

function hoursTotal(hours) { return Object.values(hours || {}).reduce((total, value) => total + (Number(value) || 0), 0); }
function itemBadge(item) { if (item.isReview) return '<span class="m2-pill m2-pill-violet">Revisão</span>'; if (item.status === 'concluido') return '<span class="m2-pill m2-pill-green">Concluído</span>'; if (item.status === 'ignorado') return '<span class="m2-pill m2-pill-gray">Ignorado</span>'; return '<span class="m2-pill m2-pill-teal">Estudo</span>'; }
function calendarCard(item) { return `<button type="button" class="m2-cal-item ${item.status === 'concluido' ? 'done' : ''} ${item.isReview ? 'review' : ''}" data-action="open-calendar-day" data-date="${item.planned_date}"><strong>${escapeHtml(item.subjectLabel)}</strong><span>${escapeHtml(item.isReview ? `Revisão · ${item.topicLabel}` : item.topicLabel)}</span><small>${item.duration_minutes} min · ${item.status === 'concluido' ? 'feito' : 'pendente'}</small></button>`; }

export function viewEntry() {
  const activeContest = (window.M2Data.contests || []).find(contest => String(contest.id) === String(state.contestId)) || window.M2Data.contests?.[0];
  return `<div class="m2-content"><div class="m2-card m2-card-hero" style="text-align:center; padding:48px 24px; max-width:680px; margin:40px auto;"><span class="m2-brandmark" style="width:56px; height:56px; margin:0 auto 16px;">${icon('graduation-cap', 32)}</span><h1 class="m2-page-title" style="font-size:28px;">Bem-vindo(a) à Mentoria 2.0</h1><p class="m2-page-subtitle" style="margin-top:8px;">Concurso selecionado: <strong>${escapeHtml(activeContest?.name || 'Nenhum concurso ativo')}</strong>.</p><div style="margin-top:24px; display:flex; justify-content:center; gap:12px; flex-wrap:wrap;"><button type="button" class="m2-btn m2-btn-primary" data-nav="today">${icon('play', 16)} Ir para Meu Estudo de Hoje</button><button type="button" class="m2-btn m2-btn-secondary" data-nav="onboarding">${icon('sparkles', 16)} Configurar plano</button></div></div></div>`;
}

export function viewOnboarding() {
  const draft = planDraft(); const step = state.onboardingStep; const subjects = window.M2Data.subjects || []; const total = hoursTotal(draft.hours); const canUseSmartCycle = (window.M2Data.capabilities || []).includes('cronograma_inteligente');
  const stepContent = step === 1 ? `
    <h2 class="m2-card-title">${icon('target', 20, 'text-teal')} Concurso e método</h2>
    <div class="m2-plan-options">${(window.M2Data.contests || []).map(contest => `<label class="m2-plan-option"><input type="radio" name="ob-contest" value="${contest.id}" ${String(draft.contestId) === String(contest.id) ? 'checked' : ''}><span><strong>${escapeHtml(contest.name)}</strong><small>${escapeHtml([contest.organization, contest.board, contest.role].filter(Boolean).join(' · ') || 'Concurso cadastrado')}</small></span></label>`).join('') || '<p class="m2-empty-inline">Nenhum concurso ativo foi disponibilizado pelo mentor.</p>'}</div>
    <h3 class="m2-plan-section-title">Como você quer estudar?</h3><div class="m2-plan-options m2-plan-options--two"><label class="m2-plan-option ${canUseSmartCycle ? '' : 'is-disabled'}"><input type="radio" name="ob-mode" value="ciclo_inteligente" ${draft.mode === 'ciclo_inteligente' ? 'checked' : ''} ${canUseSmartCycle ? '' : 'disabled'}><span><strong>${icon('zap', 16)} Ciclo inteligente</strong><small>${canUseSmartCycle ? 'Continua da próxima matéria quando sua rotina mudar.' : 'Disponível quando o produto incluir Cronograma Inteligente.'}</small></span></label><label class="m2-plan-option"><input type="radio" name="ob-mode" value="agendado" ${draft.mode === 'agendado' ? 'checked' : ''}><span><strong>${icon('calendar-days', 16)} Agenda semanal</strong><small>Distribui blocos em datas e dias específicos.</small></span></label></div>`
    : step === 2 ? `
    <h2 class="m2-card-title">${icon('clock', 20, 'text-teal')} Disponibilidade real</h2><p class="m2-page-subtitle">Defina horas líquidas por dia. Total atual: <strong>${total}h semanais</strong>.</p><div class="m2-plan-hours">${WEEKDAYS.map((name, index) => `<label>${name}<input class="m2-ob-day" data-day="${WEEKDAY_KEYS[index]}" type="number" min="0" max="24" step="0.5" value="${draft.hours[WEEKDAY_KEYS[index]] ?? 0}"><small>horas</small></label>`).join('')}</div><div class="m2-plan-settings"><label>Duração do bloco<select id="m2-ob-minutes">${[45, 50, 60, 90].map(value => `<option value="${value}" ${Number(draft.minutes) === value ? 'selected' : ''}>${value} minutos</option>`).join('')}</select></label><label>Máximo de tópicos/dia<input id="m2-ob-max-topics" type="number" min="0" value="${draft.maxTopics}"><small>0 = sem limite</small></label><label>Repetições do edital<input id="m2-ob-repetitions" type="number" min="1" value="${draft.repetitions}"></label><label>Meta de acerto<select id="m2-ob-goal">${[70, 80, 85, 90].map(value => `<option value="${value}" ${Number(draft.goal) === value ? 'selected' : ''}>${value}%</option>`).join('')}</select></label></div>`
    : step === 3 ? `
    <h2 class="m2-card-title">${icon('chart-no-axes-combined', 20, 'text-teal')} Diagnóstico por matéria</h2><p class="m2-page-subtitle">O motor prioriza peso do edital, progresso, desempenho e sua autoavaliação.</p><div class="m2-plan-subjects">${subjects.map(subject => `<div class="m2-plan-subject"><label><input class="m2-ob-subject-enabled" data-subject-id="${subject.id}" type="checkbox" ${draft.selected[subject.id] !== false ? 'checked' : ''}> ${escapeHtml(subject.name)}</label><select class="m2-ob-subject-dominance" data-subject-id="${subject.id}"><option value="iniciante" ${draft.levels[subject.id] === 'iniciante' ? 'selected' : ''}>Iniciante</option><option value="intermediario" ${draft.levels[subject.id] !== 'iniciante' && draft.levels[subject.id] !== 'avancado' ? 'selected' : ''}>Intermediário</option><option value="avancado" ${draft.levels[subject.id] === 'avancado' ? 'selected' : ''}>Avançado</option></select></div>`).join('') || '<p class="m2-empty-inline">O edital ainda não tem matérias cadastradas.</p>'}</div>`
    : `<div class="m2-plan-ready"><span class="m2-brandmark">${icon('check-circle-2', 30)}</span><h2>Revise antes de gerar</h2><div class="m2-plan-summary"><span><small>CONCURSO</small><strong>${escapeHtml((window.M2Data.contests || []).find(contest => String(contest.id) === String(draft.contestId))?.name || 'Não selecionado')}</strong></span><span><small>MÉTODO</small><strong>${draft.mode === 'ciclo_inteligente' ? 'Ciclo inteligente' : 'Agenda semanal'}</strong></span><span><small>CARGA</small><strong>${total}h por semana · ${draft.minutes} min/bloco</strong></span><span><small>MATÉRIAS</small><strong>${Object.values(draft.selected).filter(Boolean).length} ativas</strong></span></div></div>`;
  return `<div class="m2-content"><div class="m2-page-header"><div class="m2-page-title-group"><span class="m2-eyebrow">A02 · Diagnóstico inicial guiado</span><h1 class="m2-page-title">Seu plano de estudos</h1><p class="m2-page-subtitle">Passo ${step} de 4 · o cronograma será calculado com a sua disponibilidade real.</p></div><div class="m2-pill m2-pill-teal">${icon('sparkles', 14)} Motor de capacidade ativo</div></div><div class="m2-card" style="max-width:820px; margin:0 auto; width:100%;"><div class="m2-plan-steps">${[1, 2, 3, 4].map(number => `<span class="${number === step ? 'active' : number < step ? 'complete' : ''}">${number}</span>`).join('')}</div>${stepContent}<div class="m2-plan-actions">${step > 1 ? `<button type="button" class="m2-btn m2-btn-secondary" data-action="next-onboarding" data-next="${step - 1}">Voltar</button>` : ''}${step < 4 ? `<button type="button" class="m2-btn m2-btn-primary" data-action="next-onboarding" data-next="${step + 1}">Avançar ${icon('arrow-right', 16)}</button>` : `<button type="button" class="m2-btn m2-btn-primary" data-action="generate-study-plan">${icon('sparkles', 16)} Gerar plano personalizado</button>`}</div></div></div>`;
}

export function viewToday() {
  const today = dateKey(new Date()); const items = scheduleItems(); const scheduled = items.filter(item => item.planned_date === today); const cycle = items.filter(item => !item.planned_date && item.status === 'pendente').sort((a, b) => (a.cycle_position || 0) - (b.cycle_position || 0)); const next = scheduled.find(item => item.status === 'pendente') || cycle[0] || null; const student = window.M2Data.student || {};
  const banner = window.M2Data.mentorship?.student_home_banner;
  const bannerUrl = typeof banner?.url === 'string' && isSafeHtmlUrl(banner.url) ? banner.url : '';
  const bannerMarkup = bannerUrl ? `<section class="m2-student-home-banner" aria-label="Capa da mentoria"><img src="${escapeHtml(bannerUrl)}" alt="Capa da mentoria"></section>` : '';
  return `<div class="m2-content">${bannerMarkup}<div class="m2-page-header"><div class="m2-page-title-group"><span class="m2-eyebrow">A03 · ${escapeHtml(fmtDate(new Date(), { weekday: 'long', day: 'numeric', month: 'long' }))}</span><h1 class="m2-page-title">Foco na missão, ${escapeHtml((student.name || 'Estudante').split(' ')[0])}!</h1><p class="m2-page-subtitle">Seu próximo bloco vem do cronograma ativo.</p></div><button type="button" class="m2-btn m2-btn-secondary" data-nav="planning">${icon('calendar-days', 16)} Ver planejamento</button></div><div class="m2-grid-split"><div class="m2-card m2-card-hero">${next ? `<span class="m2-pill ${next.isReview ? 'm2-pill-violet' : 'm2-pill-teal'}">${next.isReview ? 'Revisão programada' : 'Próxima atividade'}</span><h2 style="margin:12px 0 4px;">${escapeHtml(next.subjectLabel)}</h2><p class="m2-page-subtitle">${escapeHtml(next.topicLabel)} · ${next.duration_minutes} minutos</p><div style="margin-top:18px;"><button type="button" class="m2-btn m2-btn-primary" data-action="open-calendar-day" data-date="${next.planned_date || 'cycle'}">${icon('play', 16)} Abrir atividade</button></div>` : `<h2>Nenhum bloco para hoje</h2><p class="m2-page-subtitle">Gere seu plano ou continue a fila de ciclo quando estiver pronto.</p><button type="button" class="m2-btn m2-btn-primary" data-nav="onboarding">Configurar plano</button>`}</div><div class="m2-card"><h2 class="m2-card-title">${icon('list-checks', 18)} Roteiro do dia</h2>${scheduled.length ? scheduled.map(item => `<div class="m2-routine-row">${itemBadge(item)}<span><strong>${escapeHtml(item.subjectLabel)}</strong><small>${escapeHtml(item.topicLabel)} · ${item.duration_minutes} min</small></span><button type="button" class="m2-btn m2-btn-quiet m2-btn-sm" data-action="open-calendar-day" data-date="${today}">Abrir</button></div>`).join('') : '<p class="m2-empty-inline">Nenhuma atividade datada para hoje.</p>'}</div></div></div>`;
}

export function viewPlanning() {
  const cursor = parseDate(state.calendarCursor) || new Date(); const items = scheduleItems({ calendar: true }); const isWeek = state.planningView === 'week'; const start = isWeek ? mondayOf(cursor) : new Date(cursor.getFullYear(), cursor.getMonth(), 1); const end = isWeek ? addDays(start, 6) : new Date(cursor.getFullYear(), cursor.getMonth() + 1, 0); const startKey = dateKey(start); const endKey = dateKey(end); const dated = items.filter(item => item.planned_date && item.planned_date >= startKey && item.planned_date <= endKey); const cycles = items.filter(item => !item.planned_date).sort((a, b) => (a.cycle_position || a.position || 0) - (b.cycle_position || b.position || 0)); const minutes = dated.reduce((sum, item) => sum + item.duration_minutes, 0); const completed = dated.filter(item => item.status === 'concluido').length; const pendingReviews = dated.filter(item => item.isReview && item.status !== 'concluido').length; const overdue = items.filter(item => item.planned_date && item.planned_date < dateKey(new Date()) && item.status === 'pendente' && !item.isReview).length; const label = isWeek ? `${fmtDate(start)} a ${fmtDate(end)}` : new Intl.DateTimeFormat('pt-BR', { month: 'long', year: 'numeric' }).format(cursor);
  const dates = []; if (isWeek) for (let index = 0; index < 7; index += 1) dates.push(addDays(start, index)); else { const leading = (start.getDay() + 6) % 7; for (let index = 0; index < leading; index += 1) dates.push(null); for (let day = 1; day <= end.getDate(); day += 1) dates.push(new Date(cursor.getFullYear(), cursor.getMonth(), day)); }
  return `<div class="m2-content"><div class="m2-page-header"><div class="m2-page-title-group"><span class="m2-eyebrow">A04 · Calendário e ciclos de estudo</span><h1 class="m2-page-title">Seu planejamento</h1><p class="m2-page-subtitle">${escapeHtml(label)} · ${(minutes / 60).toFixed(1)} horas programadas</p></div><div class="m2-planning-actions"><div class="m2-view-switch"><button type="button" class="m2-btn m2-btn-sm ${isWeek ? 'm2-btn-primary' : 'm2-btn-secondary'}" data-action="set-planning-view" data-view="week">Semana</button><button type="button" class="m2-btn m2-btn-sm ${!isWeek ? 'm2-btn-primary' : 'm2-btn-secondary'}" data-action="set-planning-view" data-view="month">Mês</button></div><button type="button" class="m2-btn m2-btn-secondary" data-action="open-replan-modal">${icon('calendar-sync', 16)} Replanejar</button></div></div>${state.mode === 'workspace' ? `<div class="m2-planning-metrics"><span><strong>${completed}/${dated.length}</strong> blocos concluídos</span><span><strong>${overdue}</strong> atrasados</span><span><strong>${pendingReviews}</strong> revisões pendentes</span><span><strong>${(minutes / 60).toFixed(1)}h</strong> planejadas</span></div>` : ''}<div class="m2-card"><div class="m2-calendar-toolbar"><button type="button" class="m2-btn m2-btn-quiet" data-action="calendar-prev" aria-label="Período anterior">${icon('chevron-left', 18)}</button><strong>${escapeHtml(label)}</strong><div><button type="button" class="m2-btn m2-btn-quiet" data-action="calendar-today">Hoje</button><button type="button" class="m2-btn m2-btn-quiet" data-action="calendar-next" aria-label="Próximo período">${icon('chevron-right', 18)}</button></div></div><div class="m2-calendar-weekdays">${WEEKDAYS.map(day => `<span>${day.slice(0, 3)}</span>`).join('')}</div><div class="m2-calendar-grid ${isWeek ? 'm2-calendar-grid--week' : 'm2-calendar-grid--month'}">${dates.map(date => { if (!date) return '<div class="m2-cal-empty"></div>'; const key = dateKey(date); const dayItems = dated.filter(item => item.planned_date === key); const today = key === dateKey(new Date()); return `<section class="m2-cal-col ${today ? 'current' : ''}"><button type="button" class="m2-cal-day-label" data-action="open-calendar-day" data-date="${key}"><span>${date.getDate()}</span><small>${isWeek ? WEEKDAYS[(date.getDay() + 6) % 7] : ''}</small></button>${dayItems.slice(0, isWeek ? 6 : 3).map(calendarCard).join('')}${dayItems.length > (isWeek ? 6 : 3) ? `<button type="button" class="m2-cal-more" data-action="open-calendar-day" data-date="${key}">+${dayItems.length - (isWeek ? 6 : 3)} atividades</button>` : ''}${dayItems.length === 0 ? '<span class="m2-cal-free">Livre</span>' : ''}</section>`; }).join('')}</div></div>${cycles.length ? `<div class="m2-card" style="margin-top:18px;"><div class="m2-card-header"><span class="m2-card-title">${icon('refresh-cw', 18)} Fila do ciclo inteligente</span><span class="m2-page-subtitle">Continue pelo próximo bloco disponível.</span></div><div class="m2-cycle-queue">${cycles.map(item => `<div class="m2-cycle-item ${item.status === 'concluido' ? 'done' : ''}"><span>${item.cycle_position || item.position || '—'}</span><div><strong>${escapeHtml(item.subjectLabel)}</strong><small>${item.duration_minutes} min · prioridade ${item.priority || 0}</small></div>${itemBadge(item)}<button type="button" class="m2-btn m2-btn-quiet m2-btn-sm" data-action="open-calendar-day" data-date="cycle">Abrir</button></div>`).join('')}</div></div>` : ''}</div>`;
}
